inline std::string GetObjectNameFromHash(uint32_t hash) {
    auto it = object_names.find(hash);
    if (it != object_names.end()) return it->second;
    char buf[32];
    snprintf(buf, sizeof(buf), xorstr_lite("0x%X"), hash);
    return std::string(buf);
}
